<?php
require_once __DIR__.'/auth.php';
if(member_logged_in())redirect('member/dashboard.php');
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim($_POST['email']??'');$pass=$_POST['password']??'';
$r=query_one("SELECT a.id account_id,a.email account_email,a.password,a.is_active,m.id member_id,m.branch_id,CONCAT(m.first_name,' ',m.last_name) name FROM member_accounts a JOIN members m ON m.id=a.member_id WHERE a.email=? LIMIT 1",[$email]);
if($r&&$r['is_active']&&password_verify($pass,$r['password'])){login_member($r);db()->prepare('UPDATE member_accounts SET last_login=NOW() WHERE id=?')->execute([$r['account_id']]);redirect('member/dashboard.php');}$error='Invalid member email or password.';}
?>
